import{_ as a,a as t}from"./chunks/Fixpipe_Channel_Split_with_dirty.CvIcEDCh.js";import{_ as i,o as p,a as l,b as s}from"./app.C41L12d5.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/cube_store_key_features"},{"text":"F32 Channel Split","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/F32-Channel-Split"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/F32-Channel-Split.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/F32-Channel-Split.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1787050286000}'),_={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_store_key_features/F32-Channel-Split.md"};function n(r,e,c,o,u,S){return p(),l("div",null,[...e[0]||(e[0]=[s('<div><article class="markdown-body"><h1>F32 Channel Split<span id="ZH-CN_TOPIC_0000002569070989"></span></h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中对于目标类型为f32，如果开启了Channel Split（通道拆分），硬件就能够将16×16的分形矩阵转换为16×8的小z分形矩阵，此时每个16×16的分形矩阵将被拆分为2个独立的16×8的小z分形矩阵。</p><p>对于DataCopy接口，可以通过配置<strong>DataCopyCO12DstParams结构体参数</strong>定义中channelSplit为true开启。</p><p>对于Fixpipe接口，可以通过配置<a href="../cube_compute_store/Fixpipe_L0CToGM.html">Fixpipe搬运参数结构体说明</a>中channelSplit为true开启。</p><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><div data-filter="A3,910b"><ul><li><p>针对如下产品型号：</p><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><p>当Fixpipe指令的输入和输出数据类型都为float，NZ输出到GM，并且不开启NZ2ND与unitFlag时，才能够开启Channel Split功能。</p></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，当Fixpipe指令的输入和输出数据类型都为float,NZ输出到GM，并且不开启NZ2ND、NZ2DN与unitFlag时，才能够开启Channel Split功能。当前搬出到L1 Buffer和Unified Buffer（UB）不支持该功能。</li></ul></div><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>完整示例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/fixpipe_l0c2gm">fixpipe_l0c2gm样例</a>场景7。</p><p>如下图所示，当开启Channel Split功能后，shape为[64,32]的源操作数将会被拆分为16个独立的16x8分形矩阵。</p><p><strong>图1</strong> F32 Channel Split示意图（无无效数据）<span id="zh-cn_topic_0000002515660950_fig222295694112"></span></p><p><img src="'+a+'" alt></p><p>当开启Channel Split功能后，nSize（源NZ矩阵在N方向上的大小）必须为8的倍数。如下图所示，shape为[64,24]的源操作数将会被拆分为3列16x8分形矩阵。</p><p><strong>图2</strong> F32 Channel Split示意图（有无效数据）<span id="zh-cn_topic_0000002515660950_fig5809145844116"></span></p><p><img src="'+t+'" alt></p></article></div>',1)])])}const f=i(_,[["render",n]]);export{I as __pageData,f as default};
